const input = $input.first().json;
const body = input.body || input;
const toolSlug = body.tool_slug || '';
const params = body.params || {};
const skills = body.skills || [];
const projectId = body.project_id || '';

// Combine all skill prompts
let skillInstructions = '';
for (const s of skills) {
  skillInstructions += `\n--- Skill: ${s.skill_key} ---\n${s.prompt || s.prompt_template || ''}\n`;
}

const systemPrompt = `Eres un asistente legal experto ejecutando la herramienta "${toolSlug}".
Sigue las instrucciones de los skills asignados.

REGLAS:
- CITA cada afirmación con [SRC-XXX]
- NO inventes datos
- Responde en español con formato estructurado`;

const userPrompt = `Herramienta: ${toolSlug}\nParámetros: ${JSON.stringify(params)}\n${skillInstructions}`;

return [{
  json: {
    execution_id: body.execution_id,
    tool_slug: toolSlug,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    model: 'default'
  }
}];

const harveyResponse = $input.first().json;
const prevData = $('Prepare from Tool Definition').first().json;
const rawResponse = harveyResponse.text || harveyResponse.completion || JSON.stringify(harveyResponse);

// Extract evidence references from response
const citationPattern = /\[SRC-\d{3}\]/g;
const citations = rawResponse.match(citationPattern) || [];
const uniqueCitations = [...new Set(citations)];

return [{
  json: {
    execution_id: prevData.execution_id,
    tool_slug: prevData.tool_slug,
    output: {
      raw_response: rawResponse,
      model_used: harveyResponse.model || 'harvey-default',
      generated_at: new Date().toISOString(),
      citations_found: uniqueCitations.length,
      citations: uniqueCitations
    },
    status: 'ok'
  }
}];
